import os
import json
from typing import Any, Dict, List, Optional

from openai import OpenAI


MODEL_ID = os.getenv("OPENAI_MODEL", "gpt-4.1-mini")


def _safe_json_loads(text: str) -> Any:
    try:
        return json.loads(text)
    except Exception:
        start = text.find("{")
        end = text.rfind("}")
        if start != -1 and end != -1 and end > start:
            return json.loads(text[start : end + 1])
        raise


def _normalize_vendor(payload: Dict[str, Any]) -> Dict[str, Any]:
    vendor = payload.get("vendor") or payload.get("merchant") or payload.get("payee")
    if isinstance(vendor, dict):
        vendor_name = vendor.get("name") or vendor.get("vendor_name") or vendor.get("text")
    else:
        vendor_name = vendor
    return {
        "name": vendor_name,
        "category": payload.get("category"),
    }


def _normalize_currency(value: Any) -> Optional[str]:
    if value is None:
        return None
    s = str(value).strip().upper()
    if len(s) == 3 and s.isalpha():
        return s
    mapping = {"$": "USD", "€": "EUR", "£": "GBP"}
    return mapping.get(s, s or None)


def _normalize_amount(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).strip()
    s = s.replace(",", "")
    for prefix in ("$", "€", "£"):
        s = s.replace(prefix, "")
    try:
        return float(s)
    except Exception:
        return None


def _normalize_date(value: Any) -> Optional[str]:
    if value is None:
        return None
    s = str(value).strip()
    return s or None


def _normalize_line_items(items: Any) -> List[Dict[str, Any]]:
    if not isinstance(items, list):
        return []
    normalized = []
    for item in items:
        if not isinstance(item, dict):
            continue
        normalized.append(
            {
                "description": item.get("description") or item.get("name") or item.get("item"),
                "quantity": item.get("quantity"),
                "unit_price": _normalize_amount(item.get("unit_price") or item.get("unitPrice")),
                "amount": _normalize_amount(item.get("amount") or item.get("total")),
                "currency": _normalize_currency(item.get("currency")),
            }
        )
    return normalized


def normalize_expense_fields(extracted_fields: Dict[str, Any]) -> Dict[str, Any]:
    """
    Normalize extracted expense fields into a standard JSON schema.

    Standard schema:
    {
      "document_type": "expense",
      "vendor": {"name": str|null, "category": str|null},
      "transaction": {
        "date": str|null,
        "currency": str|null,
        "amount": float|null,
        "tax": float|null,
        "tip": float|null,
        "total": float|null
      },
      "payment": {
        "method": str|null,
        "last4": str|null
      },
      "receipt": {
        "invoice_number": str|null,
        "receipt_number": str|null
      },
      "line_items": [
        {
          "description": str|null,
          "quantity": any,
          "unit_price": float|null,
          "amount": float|null,
          "currency": str|null
        }
      ],
      "raw": {...}
    }
    """
    payload = extracted_fields if isinstance(extracted_fields, dict) else {}

    normalized = {
        "document_type": "expense",
        "vendor": _normalize_vendor(payload),
        "transaction": {
            "date": _normalize_date(payload.get("date") or payload.get("transaction_date") or payload.get("purchase_date")),
            "currency": _normalize_currency(payload.get("currency") or payload.get("transaction_currency")),
            "amount": _normalize_amount(payload.get("amount") or payload.get("transaction_amount") or payload.get("subtotal")),
            "tax": _normalize_amount(payload.get("tax") or payload.get("tax_amount")),
            "tip": _normalize_amount(payload.get("tip") or payload.get("gratuity")),
            "total": _normalize_amount(payload.get("total") or payload.get("grand_total")),
        },
        "payment": {
            "method": payload.get("payment_method") or payload.get("payment") or payload.get("card_type"),
            "last4": payload.get("last4") or payload.get("card_last4") or payload.get("payment_last4"),
        },
        "receipt": {
            "invoice_number": payload.get("invoice_number") or payload.get("invoiceNo") or payload.get("invoice"),
            "receipt_number": payload.get("receipt_number") or payload.get("receiptNo") or payload.get("receipt"),
        },
        "line_items": _normalize_line_items(payload.get("line_items") or payload.get("items")),
        "raw": payload,
    }

    return normalized


def extract_and_normalize_expense(document_text: str) -> Dict[str, Any]:
    """
    Uses OpenAI hosted API to extract expense fields from unstructured text,
    then normalizes them into a standard JSON schema.
    """
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))

    schema = {
        "name": "expense_extraction",
        "schema": {
            "type": "object",
            "additionalProperties": True,
            "properties": {
                "vendor": {"type": ["string", "object", "null"]},
                "merchant": {"type": ["string", "object", "null"]},
                "payee": {"type": ["string", "object", "null"]},
                "category": {"type": ["string", "null"]},
                "date": {"type": ["string", "null"]},
                "transaction_date": {"type": ["string", "null"]},
                "purchase_date": {"type": ["string", "null"]},
                "currency": {"type": ["string", "null"]},
                "transaction_currency": {"type": ["string", "null"]},
                "amount": {"type": ["number", "string", "null"]},
                "transaction_amount": {"type": ["number", "string", "null"]},
                "subtotal": {"type": ["number", "string", "null"]},
                "tax": {"type": ["number", "string", "null"]},
                "tax_amount": {"type": ["number", "string", "null"]},
                "tip": {"type": ["number", "string", "null"]},
                "gratuity": {"type": ["number", "string", "null"]},
                "total": {"type": ["number", "string", "null"]},
                "grand_total": {"type": ["number", "string", "null"]},
                "payment_method": {"type": ["string", "null"]},
                "payment": {"type": ["string", "null"]},
                "card_type": {"type": ["string", "null"]},
                "last4": {"type": ["string", "null"]},
                "card_last4": {"type": ["string", "null"]},
                "payment_last4": {"type": ["string", "null"]},
                "invoice_number": {"type": ["string", "null"]},
                "invoiceNo": {"type": ["string", "null"]},
                "invoice": {"type": ["string", "null"]},
                "receipt_number": {"type": ["string", "null"]},
                "receiptNo": {"type": ["string", "null"]},
                "receipt": {"type": ["string", "null"]},
                "line_items": {"type": "array"},
                "items": {"type": "array"},
            },
        },
    }

    response = client.responses.create(
        model=MODEL_ID,
        input=[
            {
                "role": "system",
                "content": "Extract expense fields from the document text. Return only structured data.",
            },
            {
                "role": "user",
                "content": document_text,
            },
        ],
        text={
            "format": {
                "type": "json_schema",
                "name": schema["name"],
                "schema": schema["schema"],
                "strict": False,
            }
        },
    )

    extracted_text = getattr(response, "output_text", None)
    if not extracted_text:
        output = getattr(response, "output", [])
        collected = []
        for item in output:
            for content in getattr(item, "content", []) or []:
                txt = getattr(content, "text", None)
                if txt:
                    collected.append(txt)
        extracted_text = "".join(collected)

    extracted = _safe_json_loads(extracted_text) if extracted_text else {}
    return normalize_expense_fields(extracted)
